# Deep (many-level) random instances: Gamma inside a conjugate of L x| N with
#   L generated by block matrices diag(mu^q P) (P monomial, mu rational), and
#   N = { sum_{i>=1} X^i (x) D_i }  (X = block shift, D_i diagonal)  -> abelian (YES family), or
#   N replaced by arbitrary block-upper-triangular perturbations (NO-ish family).
# usage: python3 test_deep_claude.py SEED NTESTS FAMILY   FAMILY in {deep_yes, deep_no, deepqu_yes, deepqu_no}
import sys, random, time
sys.path.insert(0, __file__.rsplit('/', 1)[0])
import flint
from linalg_claude import Q, ZERO, ONE, eye, zeros, vec, unvec, is_zero_mat, Subspace
from polyccra_claude import Setup, a_test, u_layers, is_finite_cr
from groundtruth_claude import gt_qu, gt_general

seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
ntests = int(sys.argv[2]) if len(sys.argv) > 2 else 10
family = sys.argv[3] if len(sys.argv) > 3 else 'deep_yes'
R = random.Random(seed)
qu = family.startswith('deepqu')


def monomial(s, torus):
    p = list(range(s))
    R.shuffle(p)
    M = zeros(s, s)
    for i in range(s):
        val = Q(R.choice([1, -1]))
        if torus and R.random() < 0.5:
            val *= Q(R.choice([2, 3, 1]), R.choice([1, 2]))
        M[p[i], i] = val
    return M


def mexp(X):
    n = X.nrows()
    Rm, T = eye(n), eye(n)
    for k in range(1, n + 1):
        T = T * X * Q(1, k)
        if is_zero_mat(T):
            break
        Rm += T
    return Rm


def rand_GL(n):
    while True:
        P = flint.fmpq_mat(n, n, [Q(R.randint(-1, 1)) for _ in range(n * n)])
        if P.det() != 0:
            return P


def instance():
    if family.startswith('deep2'):
        m, s = 3, 2
    else:
        while True:
            m = R.choice([3, 4, 4, 5])
            s = R.choice([1, 1, 2])
            if qu or m * s <= 5:
                break
    n = m * s
    k = R.choice([2, 3])
    ells = []
    for _ in range(k):
        mu = Q(R.choice([1, -1])) if qu else Q(R.choice([1, -1, 2, 3, -2]), R.choice([1, 1, 2]))
        P = monomial(s, not qu)
        L = zeros(n, n)
        for q in range(m):
            for i in range(s):
                for j in range(s):
                    L[q * s + i, q * s + j] = (mu ** q) * P[i, j]
        ells.append(L)
    Xs = []
    for _ in range(k):
        X = zeros(n, n)
        if (family.endswith('yes') or family.endswith('yes2')):
            for i in range(1, m):
                D = [Q(R.randint(-2, 2)) for _ in range(s)]
                for q in range(m - i):
                    for t in range(s):
                        X[q * s + t, (q + i) * s + t] = D[t]
        else:
            for r in range(n):
                for c in range(n):
                    if c // s > r // s and R.random() < 0.5:
                        X[r, c] = Q(R.randint(-2, 2))
        Xs.append(X)
    vX = zeros(n, n)
    for r in range(n):
        for c in range(n):
            if c // s > r // s and R.random() < 0.6:
                vX[r, c] = Q(R.randint(-2, 2), R.choice([1, 2]))
    v = mexp(vX)
    P = rand_GL(n) if R.random() < 0.7 else eye(n)
    vi, Pi = v.inv(), P.inv()
    return [P * v * l * mexp(X) * vi * Pi for l, X in zip(ells, Xs)], (m, s, k)


stats = dict(tests=0, agree=0, mismatch=0, skipped=0)
t0 = time.time()
for t in range(ntests):
    gens, meta = instance()
    S = Setup(gens)
    try:
        if qu:
            fin, why = is_finite_cr(S.bdiag, S.d)
            assert fin
            Sgt, order = gt_qu(S)
        else:
            ok_a, info = a_test(S, random.Random(seed * 1000 + t))
            assert ok_a, "family satisfies (a)"
            Sgt, order = gt_general(S, info['_B'])
    except RuntimeError as e:
        stats['skipped'] += 1
        print(f"[{t}] skipped ({e})")
        continue
    rec = {}
    res = u_layers(S, record=rec)
    gt_mats = [unvec(b, S.d, S.d) for b in Sgt.basis]
    gt_abelian = all(is_zero_mat(X * Y - Y * X) for X in gt_mats for Y in gt_mats)
    agree = True
    last = (S.m - 1) if res[0] == 'abelian' else res[1] - 1
    for j in range(1, last + 1):
        proj = Subspace([vec(S.trunc(X, j)) for X in gt_mats], S.d * S.d)
        ours = Subspace([vec(X) for X in rec['ub'][j]], S.d * S.d)
        if not (proj == ours):
            agree = False
            print(f"   level {j}: GT dim {proj.dim} vs ours {ours.dim}")
    if (res[0] == 'abelian') != gt_abelian:
        agree = False
    stats['tests'] += 1
    stats['agree' if agree else 'mismatch'] += 1
    bits = [(h['bits_u'], h['bits_v']) for h in rec.get('hist', [])]
    print(f"[{t}] (m,s,k)={meta} d={S.d} m_alg={S.m} |quot|={order} verdict={res[0]} "
          f"GT_abelian={gt_abelian} dimU={Sgt.dim} agree={agree} bits(u,v)={bits}", flush=True)
print(family, stats, f"time {time.time() - t0:.1f}s")
